//! Bitmap fonts for the status screen, rendered from DejaVu Sans Mono
//! (Bitstream Vera / DejaVu licence: free to use and embed) by
//! make_font.py. Printable ASCII only. Each glyph is `w * h` alpha values
//! of 4 bits, two per byte, row by row, high nibble first.

pub struct Font {
    pub w: usize,
    pub h: usize,
    pub data: &'static [u8],
}

impl Font {
    /// Coverage 0..=15 of pixel (x, y) of character `c`.
    pub fn alpha(&self, c: char, x: usize, y: usize) -> u8 {
        let c = if (' '..='~').contains(&c) { c } else { '?' };
        let i = (c as usize - 32) * self.w * self.h + y * self.w + x;
        let b = self.data[i / 2];
        if i % 2 == 0 { b >> 4 } else { b & 0x0F }
    }
}

